enum VentureCopy: Int, CaseIterable {
    case language, next, guest, account, signIn, email, password, name, agree, verify, code
    case permissions, microphone, camera, allow, skip, home, insights, assistant, care, settings
    case start, stop, example, pause, ahh, eyes, done, retry, saved, empty, download, preparing
    case send, message, unavailable, screening, guestNote, demo, call, nearby, voiceNotice, privacy, terms, cancel, signOut
}

struct VentureLanguage: Identifiable, Equatable, Sendable {
    let id: String
    let name: String
    let words: [String]
    var isRTL: Bool { ["ar", "ur"].contains(id) }
