    static let all: [VentureLanguage] = rows.map { id, name, row in
        let words = row.components(separatedBy: "|")
        precondition(words.count == VentureCopy.allCases.count, "Incomplete translation: \(id)")
        return VentureLanguage(id: id, name: name, words: words)
    }

