@MainActor @Observable final class VentureLocale {
    var language: VentureLanguage {
        didSet { UserDefaults.standard.set(language.id, forKey: "venture.language") }
    }
    init() {
        let saved = UserDefaults.standard.string(forKey: "venture.language")
        language = VentureLanguage.all.first { $0.id == saved } ?? VentureLanguage.all[0]
    }
    func t(_ key: VentureCopy) -> String { language.text(key) }
    func support(_ key: VentureSupportCopy) -> String {
        VentureSupportCopy.text(key, language: language.id)
    }

    var hasTranslatedSupport: Bool { ["en", "hi", "es"].contains(language.id) }
}

// New voice and care guidance is authored offline in these three languages.
// Other languages retain the existing translated controls and show an explicit
// English-guidance notice; we never imply that these paragraphs were translated.
