    case clinic, clinicNote, telehealth, telehealthNote, voiceCare, voiceCareNote, memoryCare, memoryCareNote
    case visitPlan, visitPlanNote, source, share, directions, noNearby, analyzing, progress, englishNotice, variationNote
    case researchTitle, researchSimilarity, researchNote

    static func text(_ key: Self, language: String) -> String {
        let words = translations[language] ?? translations["en"]!
        return words[key.rawValue]
    }

